  "titleOrig": "6-7 / Six Seven (脑腐顶流梗)",
  "summary": "梗源：6-7 出自美国 rapper Skrilla 歌曲《Doot Doot (6 7)》，副歌反复唱 6-7，经 TikTok/Reels 无厘头混剪爆红；NBA 球星 LaMelo Ball（身高6尺7）助推，被《牛津/韦氏》列为年度词，是α世代社交黑话。印花机会极大：做「6-7」大字标+耸肩手势剪影，马来国民级、跨文化无门槛，是马市场最稳基础款。（印选 11-20 热点重排上架：库内真实历史热点复用，非新研究。）",
